    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .4);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    color: #d1d2d3;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.82rem;
    cursor: pointer;
    white-space: nowrap;
}

.action-btn:hover {
    background: #2c2d30;
}

/* Emoji picker */

.emoji-picker-wrapper {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    display: flex;
    gap: 2px;
    background: #1a1d21;
    border: 1px solid #2c2d30;
    border-radius: 8px;
    padding: 6px;
    box-shadow: 0 4px 12px rgba(0, 0, 0, .5);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.3rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #2c2d30;
}

/* ──────── Input Area ──────── */

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #2c2d30;
    flex-shrink: 0;
}

.message-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #2c2d30;
    border-radius: 6px;
    background: #222529;
    color: #d1d2d3;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #1164a3;
}

.message-input-area textarea::placeholder {
    color: #717274;
}

.send-btn {
    padding: 8px 20px;
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    font-size: 0.88rem;
    cursor: pointer;
    transition: background 0.15s;
    align-self: flex-end;
}

.send-btn:hover:not(:disabled) {
    background: #148567;
}

.send-btn:disabled {
    opacity: 0.4;
    cursor: default;
}

/* ──────── Thread Panel ──────── */

.thread-panel {
    width: 25%;
    min-width: 260px;
    border-left: 1px solid #2c2d30;
    background: #19171d;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    color: #9b9d9f;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #2c2d30;
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
    background: #222529;
}

.thread-root-quote .author {
    font-size: 0.85rem;
}

.thread-root-quote p {
    margin: 4px 0 0;
    font-size: 0.88rem;
    color: #d1d2d3;
    line-height: 1.4;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    margin-bottom: 10px;
}
"}

